INSERT INTO hidden_gem (id, country_code, region_id, name, description, story, category, authenticity, fit_score, crowd_level, tags, image_url) VALUES
  ('1e9a0001-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Le Jardin Secret', 'A restored historic riad garden in the medina, divided into Islamic and exotic sections, rarely visited by tour groups.', 'Built in the 16th century and restored in 2016, this garden hides behind unassuming walls near the souks.', 'place', 0.88, 0.72, 0.25, ARRAY['garden','architecture','quiet'], 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2e9a0002-0000-0000-0000-000000000002', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Mustapha Blaoui Hidden Shop', 'A labyrinthine antique shop behind an unmarked door in the Kasbah, filled with treasures collected over 40 years.', 'Mustapha has been collecting Berber jewellery, antique doors and tribal textiles since the 1980s. No sign outside — you must knock.', 'shop', 0.92, 0.65, 0.15, ARRAY['antiques','shopping','hidden'], 'https://images.pexels.com/photos/21326994/pexels-photo-21326994.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('3e9a0003-0000-0000-0000-000000000003', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Dar Cherifa Literary Cafe', 'A 16th-century riad turned literary cafe on the first floor of the oldest house in the medina. Quiet, beautiful, and free.', 'One of the few places in the medina where you can sit with a book and a coffee without being sold anything.', 'cafe', 0.85, 0.70, 0.20, ARRAY['cafe','literature','quiet'], 'https://images.pexels.com/photos/30906051/pexels-photo-30906051.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('4e9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Palais El Badi Stork Nest', 'The ruins of El Badi Palace, now home to a colony of storks that nest on the crumbling walls. Best at sunset.', 'The storks have been nesting here for decades. Locals consider them good luck. The palace itself was once the most magnificent in Morocco.', 'viewpoint', 0.80, 0.78, 0.35, ARRAY['wildlife','sunset','ruins'], 'https://images.pexels.com/photos/15260622/pexels-photo-15260622.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('5e9a0005-0000-0000-0000-000000000005', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Bou Inania Madrasa', 'A 14th-century madrasa with the finest zellige and woodcarving in Fès, often missed because it is still a working mosque.', 'Built by the Marinid sultan Abu Inan in 1356, this is one of the few religious buildings in Morocco open to non-Muslims.', 'place', 0.90, 0.75, 0.30, ARRAY['architecture','history','islamic'], 'https://images.pexels.com/photos/35548677/pexels-photo-35548677.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('6e9a0006-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Glaoui Palace Hidden Courtyard', 'A crumbling 18th-century palace with stunning tilework, partially restored by a local artist. Hard to find, worth the search.', 'The Glaoui family once controlled the Atlas trade routes. Their Fès palace is now a quiet artist''s residence.', 'place', 0.87, 0.60, 0.10, ARRAY['architecture','art','hidden'], 'https://images.pexels.com/photos/31221481/pexels-photo-31221481.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7e9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Bluedoor Cafe Seffarin', 'A tiny cafe overlooking Seffarin Square where bookbinders still work by hand. Order mint tea and watch.', 'The square has been the centre of Fès bookbinding for 600 years. The cafe is above a workshop.', 'cafe', 0.83, 0.68, 0.20, ARRAY['cafe','crafts','books'], 'https://images.pexels.com/photos/30906049/pexels-photo-30906049.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8e9a0008-0000-0000-0000-000000000008', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Fossil Beds Near Erfoud', 'Prehistoric fossil beds where you can hunt for trilobites and ammonites with a local guide. Most visitors never know this exists.', 'The Sahara around Erfoud sits on a 400-million-year-old seabed. Local guides can take you to dig sites.', 'place', 0.90, 0.55, 0.12, ARRAY['fossils','geology','adventure'], 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('9e9a0009-0000-0000-0000-000000000009', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Khamlia Gnawa Music Night', 'An intimate evening of Gnawa music in a village home, far from any tourist circuit. Tea, drums, and dancing under the stars.', 'The Gnawa people of Khamlia are descendants of sub-Saharan musicians. Their music is recognised by UNESCO.', 'place', 0.95, 0.80, 0.18, ARRAY['music','culture','night'], 'https://images.pexels.com/photos/30374209/pexels-photo-30374209.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ae9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Diabat Old Kasbah', 'A ruined coastal kasbah south of Essaouira, once a pirate stronghold. Now a quiet walk with ocean views.', 'The kasbah was built in the 18th century to defend against pirates. It inspired Jimi Hendrix, who visited in 1969.', 'place', 0.82, 0.65, 0.15, ARRAY['ruins','coast','history'], 'https://images.pexels.com/photos/11588733/pexels-photo-11588733.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('be9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Argan Oil Women''s Cooperative', 'A women-run cooperative where Berber women press argan oil by hand. Visit, watch, and buy directly from them.', 'Over 60 cooperatives in the Essaouira region now give women economic independence through argan production.', 'shop', 0.88, 0.72, 0.22, ARRAY['argan','women','crafts'], 'https://images.pexels.com/photos/9756598/pexels-photo-9756598.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ce9a0012-0000-0000-0000-000000000012', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Sidi Kaouk Beach', 'A wild beach 25km south of Essaouira with no facilities, no crowds, and perfect waves. Bring your own everything.', 'Locals come here for weekend picnics. The road is rough, which keeps the crowds away.', 'viewpoint', 0.85, 0.60, 0.10, ARRAY['beach','wild','surf'], 'https://images.pexels.com/photos/7835701/pexels-photo-7835701.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('de9a0013-0000-0000-0000-000000000013', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Habous Quarter Book Market', 'A small book market in the Habous (New Medina) district, with rare French and Arabic titles. Almost no tourists.', 'The Habous district was built by the French in the 1930s as a model medina. The book market is a local secret.', 'shop', 0.80, 0.55, 0.15, ARRAY['books','market','hidden'], 'https://images.pexels.com/photos/19280616/pexels-photo-19280616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ee9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Ain Diab Coastline Walk', 'The Corniche from Ain Diab to the lighthouse, best at sunset. Locals come here to breathe sea air away from the city.', 'The Casablanca Corniche was renovated in 2020. The walk from Ain Diab to El Hank lighthouse is 4km of ocean views.', 'viewpoint', 0.75, 0.70, 0.30, ARRAY['coast','sunset','walk'], 'https://images.pexels.com/photos/30668291/pexels-photo-30668291.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('fe9a0015-0000-0000-0000-000000000015', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Abderrahman Slaoui Museum', 'A small museum in an art deco villa showcasing Moroccan jewellery, posters and photography. A quiet cultural gem.', 'Abderrahman Slaoui was a Moroccan collector. His villa is now a museum, rarely on tourist itineraries.', 'place', 0.85, 0.50, 0.12, ARRAY['museum','art','history'], 'https://images.pexels.com/photos/24039214/pexels-photo-24039214.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('1f9a0001-0000-0000-0000-000000000001', 'b2222222-0000-0000-0000-000000000002', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Bahia Palace Guided Tour', 'A guided tour of the 19th-century Bahia Palace, exploring its 150 rooms, courtyards and stunning zellige tilework.', ARRAY['en','fr','es','ary-Latn'], 6, 1, '{}', 1, 15, 90, 2, 'active', 'https://images.pexels.com/photos/10306569/pexels-photo-10306569.png?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2f9a0002-0000-0000-0000-000000000002', 'b2222222-0000-0000-0000-000000000002', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Saadian Tombs & El Badi Palace Walk', 'A guided walk through the Saadian Tombs and the ruins of El Badi Palace, two of Marrakech''s most historic sites.', ARRAY['en','fr','es','ary-Latn'], 8, 2, '{}', 1, 12, 120, 2, 'active', 'https://images.pexels.com/photos/20740159/pexels-photo-20740159.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
