  ('4f9a0004-0000-0000-0000-000000000004', '3a9a0003-0000-0000-0000-000000000003', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Jemaa el-Fnaa Night Food Tour', 'An evening food tour through the night market stalls of Jemaa el-Fnaa, tasting 10 street food specialities.', ARRAY['en','fr','ary-Latn','ber'], 10, 2, '{}', 1, 8, 150, 2, 'active', 'https://images.pexels.com/photos/18274601/pexels-photo-18274601.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('5f9a0005-0000-0000-0000-000000000005', '3a9a0003-0000-0000-0000-000000000003', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Moroccan Pastries Tasting', 'A tasting of traditional Moroccan pastries — chebakia, kaab el ghazal, briouat — with mint tea on a rooftop.', ARRAY['en','fr','es','ary-Latn'], 5, 1, '{}', 1, 12, 60, 1, 'active', 'https://images.pexels.com/photos/18077172/pexels-photo-18077172.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('6f9a0006-0000-0000-0000-000000000006', '1a9a0001-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Imlil Village Day Hike', 'A day hike from Imlil to traditional Berber villages in the Atlas Mountains, with lunch in a local home.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 3, '{}', 1, 10, 420, 2, 'active', 'https://images.pexels.com/photos/35449705/pexels-photo-35449705.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7f9a0007-0000-0000-0000-000000000007', '1a9a0001-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Ourika Valley Berber Village Walk', 'A guided walk through Berber villages in the Ourika Valley, with a visit to a traditional house and mint tea.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 2, '{}', 1, 12, 300, 2, 'active', 'https://images.pexels.com/photos/37684113/pexels-photo-37684113.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8f9a0008-0000-0000-0000-000000000008', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Leather Goods Workshop', 'Learn to make a small leather pouch with a master leatherworker in the Marrakech souk.', ARRAY['en','fr','es','ary-Latn'], 12, 1, '{}', 1, 4, 120, 1, 'active', 'https://images.pexels.com/photos/21326994/pexels-photo-21326994.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('9f9a0009-0000-0000-0000-000000000009', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Traditional Hammam Experience', 'A traditional Moroccan hammam experience with steam, black soap scrub and argan oil massage.', ARRAY['en','fr','es','ary-Latn'], 12, 1, '{}', 1, 6, 90, 2, 'active', 'https://images.pexels.com/photos/33279021/pexels-photo-33279021.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('af9a0010-0000-0000-0000-000000000010', 'b2222222-0000-0000-0000-000000000002', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Souks of Marrakech Guided Walk', 'A 3-hour guided walk through the labyrinthine souks of Marrakech, visiting spice, textile, metal and leather workshops.', ARRAY['en','fr','es','ary-Latn'], 8, 2, '{}', 1, 12, 180, 2, 'active', 'https://images.pexels.com/photos/35787276/pexels-photo-35787276.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('bf9a0011-0000-0000-0000-000000000011', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Gnawa Music Evening in Marrakech', 'An evening of live Gnawa music in a medina riad, with tea and traditional snacks. Learn the krakebs!', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 15, 120, 2, 'active', 'https://images.pexels.com/photos/30374209/pexels-photo-30374209.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('cf9a0012-0000-0000-0000-000000000012', '1a9a0001-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Atlas Mountains Horseback Ride', 'A half-day horseback ride through Atlas Mountain trails and Berber villages, suitable for beginners.', ARRAY['en','fr','es','ary-Latn'], 10, 2, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/35292015/pexels-photo-35292015.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('df9a0013-0000-0000-0000-000000000013', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Fès El-Bali Full Medina Walk', 'A full-day guided walk through the 9,000 alleys of Fès el-Bali, the world''s largest car-free urban area.', ARRAY['en','fr','es','it','ary-Latn','ber'], 10, 3, '{}', 1, 10, 360, 3, 'active', 'https://images.pexels.com/photos/28582578/pexels-photo-28582578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ef9a0014-0000-0000-0000-000000000014', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Bab Bou Jeloud & Madrasas Tour', 'A guided tour of the iconic Blue Gate, Bou Inania Madrasa and Attarine Madrasa — the finest Islamic architecture in Fès.', ARRAY['en','fr','es','it','ary-Latn'], 8, 2, '{}', 1, 12, 150, 3, 'active', 'https://images.pexels.com/photos/33514523/pexels-photo-33514523.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ff9a0015-0000-0000-0000-000000000015', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Fès Blue Pottery Painting Workshop', 'Learn the famous Fès blue pottery technique with a master ceramicist. Take your painted tile home.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/35201199/pexels-photo-35201199.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('1f9a0016-0000-0000-0000-000000000016', 'b6666666-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Fès Andalusian Music Dinner', 'A traditional Fassi dinner accompanied by live Andalusian music in a restored medina palace.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 2, 20, 150, 3, 'active', 'https://images.pexels.com/photos/31497982/pexels-photo-31497982.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2f9a0017-0000-0000-0000-000000000017', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Fès Chouara Tannery & Leather Souk', 'A guided visit to the Chouara tannery, watching workers dye leather by hand as they have for 1,000 years.', ARRAY['en','fr','es','it','ary-Latn'], 10, 2, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/38112312/pexels-photo-38112312.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('3f9a0018-0000-0000-0000-000000000018', '8a9a0008-0000-0000-0000-000000000008', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Dar Attamani Family Room (per night)', 'A family room in a traditional Fassi guesthouse, sleeping up to 4, with breakfast on the rooftop.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/10573397/pexels-photo-10573397.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('4f9a0019-0000-0000-0000-000000000019', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Bookbinding Workshop in Seffarin', 'Learn traditional Fès bookbinding with a master binder in Seffarin Square, the bookbinding quarter for 600 years.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 1, '{}', 1, 4, 150, 2, 'active', 'https://images.pexels.com/photos/35097550/pexels-photo-35097550.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('5f9a0020-0000-0000-0000-000000000020', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Fès Medina Photography Walk', 'A guided photography walk through the most photogenic corners of Fès el-Bali, with tips from a local photographer.', ARRAY['en','fr','es','it','ary-Latn'], 12, 2, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/38112660/pexels-photo-38112660.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('6f9a0021-0000-0000-0000-000000000021', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'desert_experience', '4x4 Desert Safari to Nomad Camp', 'A full-day 4x4 safari across the Erg Chebbi dunes, visiting nomad camps, fossil beds and an oasis.', ARRAY['en','fr','es','it','ary-Latn','ber'], 8, 2, '{}', 1, 6, 480, 3, 'active', 'https://images.pexels.com/photos/10658203/pexels-photo-10658203.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7f9a0022-0000-0000-0000-000000000022', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'desert_experience', 'Desert Stargazing Night', 'An evening of stargazing with a local astronomer at a desert camp. Telescopes and hot mint tea included.', ARRAY['en','fr','es','it','ary-Latn','ber'], 5, 1, '{}', 1, 12, 120, 3, 'active', 'https://images.pexels.com/photos/8357639/pexels-photo-8357639.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8f9a0023-0000-0000-0000-000000000023', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'desert_experience', 'Sunrise Camel Trek', 'A pre-dawn camel trek to the top of the Erg Chebbi dunes to watch the sunrise over the Sahara.', ARRAY['en','fr','es','it','ary-Latn','ber'], 5, 2, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/12378901/pexels-photo-12378901.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('9f9a0024-0000-0000-0000-000000000024', 'b3333333-0000-0000-0000-000000000003', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Nomad Family Lunch Experience', 'Share a traditional lunch with a nomadic Berber family in their desert tent. Bread baked in the sand.', ARRAY['en','fr','ary-Latn','ber'], 8, 2, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/2287528/pexels-photo-2287528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('af9a0025-0000-0000-0000-000000000025', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Todra Gorge Day Trip', 'A day trip from Merzouga to the towering Todra Gorge, with a guided walk through the canyon and palm groves.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 2, '{}', 1, 8, 480, 2, 'active', 'https://images.pexels.com/photos/33898633/pexels-photo-33898633.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('bf9a0026-0000-0000-0000-000000000026', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Budget Desert Camp (per night)', 'A simple but comfortable desert camp at the dune base, with shared facilities and dinner included.', ARRAY['en','fr','ary-Latn','ber'], 0, 1, '{}', 1, 8, 1440, 2, 'active', 'https://images.pexels.com/photos/9349466/pexels-photo-9349466.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('cf9a0027-0000-0000-0000-000000000027', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Essaouira Fishing Port & Harbor Walk', 'A guided walk through the bustling fishing port, watching the daily catch being unloaded and sold.', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 12, 90, 1, 'active', 'https://images.pexels.com/photos/6662921/pexels-photo-6662921.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('df9a0028-0000-0000-0000-000000000028', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Essaouira Ramparts & Skala de la Kasbah', 'A guided walk along the 18th-century ramparts and the Skala de la Kasbah, with views of the Atlantic and the port.', ARRAY['en','fr','es','ary-Latn'], 6, 1, '{}', 1, 15, 90, 2, 'active', 'https://images.pexels.com/photos/15289893/pexels-photo-15289893.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ef9a0029-0000-0000-0000-000000000029', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Argan Oil Cooperative Visit', 'Visit a women''s argan oil cooperative, watch the pressing process and buy directly from the women who make it.', ARRAY['en','fr','es','ary-Latn'], 6, 1, '{}', 1, 10, 60, 1, 'active', 'https://images.pexels.com/photos/9756598/pexels-photo-9756598.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ff9a0030-0000-0000-0000-000000000030', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Essaouira Beach Horse Ride', 'A 2-hour horseback ride along Essaouira''s wide beach at sunset, suitable for all levels.', ARRAY['en','fr','es','ary-Latn'], 10, 2, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/35292015/pexels-photo-35292015.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('1f9a0031-0000-0000-0000-000000000031', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Essaouira Seafood Grilled Lunch', 'A fresh seafood lunch at the port — fish grilled right in front of you, caught the same morning.', ARRAY['en','fr','ary-Latn','ber'], 8, 1, '{}', 1, 8, 60, 2, 'active', 'https://images.pexels.com/photos/6662921/pexels-photo-6662921.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2f9a0032-0000-0000-0000-000000000032', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Essaouira Thuya Wood Workshop', 'Learn to carve thuya wood — a local Essaouira speciality — with a master woodworker in the medina.', ARRAY['en','fr','es','ary-Latn'], 10, 1, '{}', 1, 4, 90, 1, 'active', 'https://images.pexels.com/photos/18373966/pexels-photo-18373966.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('3f9a0033-0000-0000-0000-000000000033', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Riad Mogador Budget Room (per night)', 'A simple, clean room within the Essaouira ramparts. Shared terrace with ocean views.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 1, 'active', 'https://images.pexels.com/photos/25254928/pexels-photo-25254928.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('4f9a0034-0000-0000-0000-000000000034', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Diabat Kasbah & Beach Walk', 'A guided walk to the ruined Diabat Kasbah and wild beach south of Essaouira, with stories of pirates and Hendrix.', ARRAY['en','fr','es','ary-Latn'], 8, 2, '{}', 1, 10, 150, 1, 'active', 'https://images.pexels.com/photos/11588733/pexels-photo-11588733.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('5f9a0035-0000-0000-0000-000000000035', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Casablanca Old Medina Walk', 'A guided walk through the old medina of Casablanca, a working market rarely visited by tourists.', ARRAY['en','fr','es','it','ary-Latn'], 10, 2, '{}', 1, 12, 120, 2, 'active', 'https://images.pexels.com/photos/19280616/pexels-photo-19280616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('6f9a0036-0000-0000-0000-000000000036', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Habous Quarter & New Medina Walk', 'A guided walk through the Habous district, a 1930s French-built model medina with traditional architecture.', ARRAY['en','fr','es','it','ary-Latn'], 8, 1, '{}', 1, 12, 120, 2, 'active', 'https://images.pexels.com/photos/34357224/pexels-photo-34357224.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7f9a0037-0000-0000-0000-000000000037', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Casablanca Seafood Dinner', 'A seafood dinner at a Casablanca seafront restaurant, with fresh catch from the Atlantic that morning.', ARRAY['en','fr','ary-Latn','ber'], 10, 1, '{}', 1, 10, 120, 3, 'active', 'https://images.pexels.com/photos/30668291/pexels-photo-30668291.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8f9a0038-0000-0000-0000-000000000038', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Casablanca Corniche Sunset Walk', 'A guided sunset walk along the Ain Diab Corniche, from the beach clubs to El Hank lighthouse.', ARRAY['en','fr','es','it','ary-Latn'], 8, 1, '{}', 1, 15, 90, 1, 'active', 'https://images.pexels.com/photos/30668291/pexels-photo-30668291.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('9f9a0039-0000-0000-0000-000000000039', 'da9a0013-0000-0000-0000-000000000013', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Hotel Atlas Business Room (per night)', 'A business-class room with sea view, breakfast and free airport shuttle.', ARRAY['en','fr','es','it','ru','ary-Arab'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/6587480/pexels-photo-6587480.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('af9a0040-0000-0000-0000-000000000040', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Casablanca Pastry & Coffee Tour', 'A morning tour of Casablanca''s best patisseries and coffee houses, from French-style to Moroccan traditional.', ARRAY['en','fr','ary-Latn','ber'], 8, 1, '{}', 1, 8, 120, 1, 'active', 'https://images.pexels.com/photos/18077172/pexels-photo-18077172.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('bf9a0041-0000-0000-0000-000000000041', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Casablanca Cathedral & Mohammed V Square', 'A guided walk to the Sacré-Cœur Cathedral and Mohammed V Square, the heart of French colonial Casablanca.', ARRAY['en','fr','es','it','ary-Latn'], 8, 1, '{}', 1, 15, 90, 2, 'active', 'https://images.pexels.com/photos/30367293/pexels-photo-30367293.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('cf9a0042-0000-0000-0000-000000000042', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Casablanca Hammam & Spa Afternoon', 'A relaxing afternoon at a traditional hammam with steam, scrub, and argan oil massage.', ARRAY['en','fr','es','ary-Latn'], 12, 1, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/33279021/pexels-photo-33279021.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
